DROP PROCEDURE sp_billing_new_preview$$
CREATE PROCEDURE sp_billing_new_preview(
    pBRANCHID     Int
    ,pBILLINGNO   Varchar(20)
    ,pENCODER     Int 
)
BEGIN
Declare lvBranchDBName  Varchar(200)   DEFAULT '';

Set @svAPPROVEDBY     =  Null;
Set @svBRANCHNAME     =  Null;
Set @svBRANCHADDRESS  =  Null;
Set @svTRANSTYPE      =  Null;
Set lvBranchDBName = sp_mrcretails.fn_GetMrcDBName(pBRANCHID);
If TRIM(lvBranchDBName) != '' THEN
    Set lvBranchDBName = CONCAT(lvBranchDBName, '.');
End if;

Set @svAPPROVEDBY     =  Null;
Set @svBRANCHNAME     =  Null;
Set @svBRANCHADDRESS  =  Null;
Set @sql = Concat("SELECT MANAGER,BRANCHNAME,ADDRESS Into @svAPPROVEDBY,@svBRANCHNAME,@svBRANCHADDRESS  FROM ",lvBranchDBName ,"branch Where BRANCHID=",pBRANCHID ," Limit 1 ");
PREPARE STMT FROM @sql;
EXECUTE STMT;
DEALLOCATE PREPARE STMT;

Set @svPREPAREDBY = Null;
Set @sql = Concat("
    Set @svPREPAREDBY = Ifnull(
                      (SELECT
                        Concat(emp.LASTNAME, ', ', emp.FIRSTNAME
                                ,Case when length(trim(ifnull(emp.MIDDLENAME,'')))>0 then Concat(' ',left(emp.MIDDLENAME,1) ,'.')  else ' ' end
                         ) as EMPLOYEENAME
                      FROM   ",lvBranchDBName ,"employees as emp where EMPID =  ",pENCODER ,"  limit 1) 
    , '');
");
PREPARE STMT FROM @sql;
EXECUTE STMT;
DEALLOCATE PREPARE STMT;

Set @sql = Concat("Set @svTRANSTYPE = (SELECT TRANSTYPE FROM ",lvBranchDBName ,"billing_new Where BILLINGNO='",pBILLINGNO,"' Limit 1)");
PREPARE STMT FROM @sql;
EXECUTE STMT;
DEALLOCATE PREPARE STMT;
Set @svTRANSTYPE = trim(ifnull(@svTRANSTYPE,''));


-- CUSTOMER, ADDRESS, BILLPRD, PASTDUE, CURRENT, TTLDUE, NOTYETDUE, refdate, INVOICE, TERM, ddate, TRA, INVAMT
-- , PDC, pdate, RECEIPT, DEBIT, CREDIT, BALANCE, BRNCODE, BillType, BRANCHNAME, BRANCHADDRESS, PREPAREDBY, APPROVEDBY
if @svTRANSTYPE="SRVC" Then
    Set @sql = Concat("
        SELECT Distinct
            cus.CUSTOMERNAME as CUSTOMER
            ,cus.ADDRESS as ADDRESS
            ,libTRANSTYPE.Description as TRANSTYPE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVDUE,0) Else ifnull(bill_new.TTLJODUE,0) End)  as PASTDUE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVCUR,0) Else ifnull(bill_new.TTLJOCUR,0) End)  as CURRENT
            ,( 
                (Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVDUE,0) Else ifnull(bill_new.TTLJODUE,0) End)
                + 
                (Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVCUR,0) Else ifnull(bill_new.TTLJOCUR,0) End)
             ) as TTLDUE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVNYDUE,0) Else ifnull(bill_new.TTLJONYDUE,0) End)  as NOTYETDUE
            
            ,Ucase(Date_format(CUT_OFF,'%b. %d, %Y')) as BILLPRD
            ,Date_Format(bill_dtls.REFDATE,'%m/%d/%Y') as refdate
            ,bill_dtls.REFSPINVNO  as INVOICE
            ,bill_dtls.TERMS as TERM
            ,Date_Format(bill_dtls.DUEDATE,'%m/%d/%Y') AS ddate
            ,bill_dtls.REFJONO AS TRA
            ,bill_dtls.REFINVAMOUNT AS INVAMT
            ,bill_dtls.PDC_ISSUED as PDC
            ,bill_dtls.PDC_DATE as pdate
            ,bill_dtls.PDC_RECEIPT as RECEIPT
            ,(bill_dtls.DM) AS DEBIT
            ,(bill_dtls.CM + bill_dtls.PAYMENT + bill_dtls.SALRET) AS CREDIT
            ,bill_dtls.BALANCE as  BALANCE
            ,' ' AS BRNCODE
            ,UCASE(
               Case
                  When Trim(bill_dtls.REFSPINVNO)<>'' Then  'Spareparts'
                  Else 'Service'
               End
            )AS BillType
            ,UCASE(
              Case
                  When bill_dtls.MONTHDIFF > 0 Then 'Past Due'
                  When bill_dtls.MONTHDIFF = 0 Then 'Current'
                  Else 'Not Yet Due'
               End
            ) as ACCOUNT_STAT
            
            ,Ucase(fn_ToString(ifnull(@svBRANCHNAME,''))) as BRANCHNAME
            ,Ucase(fn_ToString(ifnull(@svBRANCHADDRESS,''))) as BRANCHADDRESS
            ,Ucase(fn_ToString(ifnull(@svPREPAREDBY,''))) as PREPAREDBY
            ,Ucase(fn_ToString(ifnull(@svAPPROVEDBY,''))) as APPROVEDBY
            ,bill_new.BILLINGNO
            ,Cast(ifnull(srvcJO.REMARKS,'') as Char) as ACCOUNTNO 
            ,ifnull(srvcCus.PLATENO,'') as PLATENO
        FROM ",lvBranchDBName ,"billing_new_dtls as bill_dtls
          Join ",lvBranchDBName ,"billing_new as bill_new On bill_dtls.BILLINGNO =  bill_new.BILLINGNO
          Join ",lvBranchDBName ,"customer as cus on bill_new.customerid =  cus.customerid
          Join ",lvBranchDBName ,"billing_new_main as bill_main on bill_new.BMAINID = bill_main.BMAINID
          Left Join sp_mrcretails.library as libTRANSTYPE on  bill_new.TRANSTYPE = libTRANSTYPE.LibCode  And libTRANSTYPE.ParentCode='TRANSTYPE'
          Left Join ",lvBranchDBName ,"srvcjoborder  as srvcJO on bill_dtls.REFJONO = srvcJO.JOBORDERNO and ifnull(bill_dtls.JOBORDERID,0) = ifnull(srvcJO.JOBORDERID,0)
          Left Join ",lvBranchDBName ,"srvcustomer as srvcCus on srvcJO.CUSTOMERID = srvcCus.CUSTOMERID   and srvcJO.ACCOUNTNO = srvcCus.ACCOUNTNO
        Where bill_dtls.BILLINGNO='",pBILLINGNO,"'
        Order By bill_dtls.MONTHDIFF Desc,bill_dtls.DUEDATE Asc;
    ");

Else
      Set @sql = Concat("
        SELECT
            cus.CUSTOMERNAME as CUSTOMER
            ,cus.ADDRESS as ADDRESS
            ,libTRANSTYPE.Description as TRANSTYPE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVDUE,0) Else ifnull(bill_new.TTLJODUE,0) End)  as PASTDUE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVCUR,0) Else ifnull(bill_new.TTLJOCUR,0) End)  as CURRENT
            ,( 
                (Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVDUE,0) Else ifnull(bill_new.TTLJODUE,0) End)
                + 
                (Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVCUR,0) Else ifnull(bill_new.TTLJOCUR,0) End)
             ) as TTLDUE
            ,(Case When bill_new.TRANSTYPE = 'SPTR' Then ifnull(bill_new.TTLINVNYDUE,0) Else ifnull(bill_new.TTLJONYDUE,0) End)  as NOTYETDUE
            
            ,Ucase(Date_format(CUT_OFF,'%b. %d, %Y')) as BILLPRD
            ,Date_Format(bill_dtls.REFDATE,'%m/%d/%Y') as refdate
            ,bill_dtls.REFSPINVNO  as INVOICE
            ,bill_dtls.TERMS as TERM
            ,Date_Format(bill_dtls.DUEDATE,'%m/%d/%Y') AS ddate
            ,bill_dtls.REFJONO AS TRA
            ,bill_dtls.REFINVAMOUNT AS INVAMT
            ,bill_dtls.PDC_ISSUED as PDC
            ,bill_dtls.PDC_DATE as pdate
            ,bill_dtls.PDC_RECEIPT as RECEIPT
            ,(bill_dtls.DM) AS DEBIT
            ,(bill_dtls.CM + bill_dtls.PAYMENT + bill_dtls.SALRET) AS CREDIT
            ,bill_dtls.BALANCE as  BALANCE
            ,' ' AS BRNCODE
            ,UCASE(
               Case
                  When Trim(bill_dtls.REFSPINVNO)<>'' Then  'Spareparts'
                  Else 'Service'
               End
            )AS BillType
            ,UCASE(
              Case
                  When bill_dtls.MONTHDIFF > 0 Then 'Past Due'
                  When bill_dtls.MONTHDIFF = 0 Then 'Current'
                  Else 'Not Yet Due'
               End
            ) as ACCOUNT_STAT
            
            ,Ucase(fn_ToString(ifnull(@svBRANCHNAME,''))) as BRANCHNAME
            ,Ucase(fn_ToString(ifnull(@svBRANCHADDRESS,''))) as BRANCHADDRESS
            ,Ucase(fn_ToString(ifnull(@svPREPAREDBY,''))) as PREPAREDBY
            ,Ucase(fn_ToString(ifnull(@svAPPROVEDBY,''))) as APPROVEDBY
            ,bill_new.BILLINGNO
            ,Cast(ifnull(spINV.SPPONO,'') as Char) as ACCOUNTNO 
            ,' ' as PLATENO
        FROM ",lvBranchDBName ,"billing_new_dtls as bill_dtls
        Join ",lvBranchDBName ,"billing_new as bill_new On bill_dtls.BILLINGNO =  bill_new.BILLINGNO
        Join ",lvBranchDBName ,"customer as cus on bill_new.customerid =  cus.customerid
        Join ",lvBranchDBName ,"billing_new_main as bill_main on bill_new.BMAINID = bill_main.BMAINID
        Left Join sp_mrcretails.library as libTRANSTYPE on  bill_new.TRANSTYPE = libTRANSTYPE.LibCode  And libTRANSTYPE.ParentCode='TRANSTYPE'
        Left Join ",lvBranchDBName ,"spinvoice as spINV on bill_new.CUSTOMERID  =  spINV.CUSTOMERID  and bill_dtls.REFSPINVNO = spINV.SPINVNO
        Where bill_dtls.BILLINGNO='",pBILLINGNO,"'
        Order By bill_dtls.MONTHDIFF Desc,bill_dtls.DUEDATE Asc;
    ");
End If;

PREPARE STMT FROM @sql;
EXECUTE STMT;
DEALLOCATE PREPARE STMT;

END
$$

